const groups={},tests=[];let lines=[];const test=(name,run)=>tests.push({name,run});const log=(...args)=>lines.push(args.join(' '));async function runTests(){for(const {name,run}of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}const attempt=fn=>{try{const v=fn();return v===undefined?'ok':v}catch(e){return e.name}};

const make=(html,attrs='')=>{const f=document.createElement('form');f.innerHTML='<select name=s '+attrs+'>'+html+'</select>';return[f,f.firstChild]};
const snap=(name,f,s)=>log(name,JSON.stringify({index:s.selectedIndex,value:s.value,flags:Array.from(s.querySelectorAll('option'),o=>o.selected),checked:Array.from(s.querySelectorAll(':checked'),o=>o.value),entries:Array.from(new FormData(f))}));
test('select-defaults',()=>{for(const [html,attrs]of [['<option>A</option><option>B</option>',''],['<option disabled>A</option><option>B</option>',''],['<option selected>A</option><option selected>B</option>',''],['<option>A</option><option>B</option>','size=2'],['<option>A</option><option>B</option>','multiple'],['<optgroup disabled><option>A</option></optgroup><option>B</option>','']]){const[f,s]=make(html,attrs);snap(html+' '+attrs,f,s)}});
test('select-selected-index',()=>{const[f,s]=make('<option value=a>A</option><option value=b>B</option>');for(const v of [-1,1,0,2,'1',1.8,null,undefined,4294967297]){s.selectedIndex=v;snap(String(v),f,s)}});
test('select-value',()=>{for(const attrs of ['', 'multiple']){const[f,s]=make('<option value=a>A</option><option value=a>AA</option><option value=b>B</option>',attrs);for(const v of ['a','b','missing','a']){s.value=v;snap(attrs+' '+v,f,s)}}});
test('option-setter',()=>{for(const attrs of ['', 'multiple', 'size=2']){const[f,s]=make('<option>A</option><option>B</option><option>C</option>',attrs),o=s.querySelectorAll('option');for(const [i,v]of [[1,true],[2,true],[2,false],[0,false],[1,false]]){o[i].selected=v;snap(attrs+' '+i+' '+v,f,s)}}});
test('option-attribute',()=>{const[f,s]=make('<option>A</option><option>B</option>'),o=s.querySelectorAll('option');snap('initial',f,s);o[1].setAttribute('selected','');snap('set B',f,s);o[0].setAttribute('selected','');snap('set A',f,s);o[0].removeAttribute('selected');snap('remove A',f,s);o[1].selected=false;snap('dirty B',f,s);o[1].removeAttribute('selected');o[1].setAttribute('selected','');snap('dirty B attribute',f,s);f.reset();snap('reset',f,s)});
test('select-mutation',()=>{const[f,s]=make('<option>A</option><option>B</option>');s.selectedIndex=-1;snap('none',f,s);const c=document.createElement('option');c.textContent='C';s.append(c);snap('append C',f,s);s.selectedIndex=1;snap('B',f,s);s.firstChild.remove();snap('remove A',f,s);s.firstChild.remove();snap('remove B',f,s);const d=document.createElement('option');d.textContent='D';d.selected=true;s.prepend(d);snap('prepend selected D',f,s);s.setAttribute('multiple','');snap('multiple',f,s);c.selected=true;snap('C true',f,s);s.removeAttribute('multiple');snap('single',f,s)});
test('select-copy',()=>{const[f,s]=make('<option selected>A</option><option>B</option>');s.selectedIndex=1;const c=s.cloneNode(true);f.append(c);snap('original',f,s);snap('copy',f,c);f.reset();snap('original reset',f,s);snap('copy reset',f,c)});
test('option-text-value',()=>{const[f,s]=make('<option>  A\n B  </option><option label=L> X<script>bad<\/script> Y </option>');snap('text',f,s);s.selectedIndex=1;snap('script text',f,s);const o=s.lastChild;log('option values',JSON.stringify([o.value,o.text,o.label,o.defaultSelected,o.index,o.form===f]));o.value='new';snap('new value',f,s)});

test('selected-options-live',()=>{const[f,s]=make('<option id=a value=a>A</option><option name=b value=b>B</option>');const c=s.selectedOptions;log('collection',c===s.selectedOptions,Object.prototype.toString.call(c),c instanceof HTMLCollection,Array.isArray(c),c.length,c.item(0)?.id,c.namedItem('a')?.value);s.selectedIndex=1;log('index',c.length,c[0]?.value,c.namedItem('a'),c.namedItem('b')?.value);s.selectedIndex=-1;log('empty',c.length,c[0]);s.setAttribute('multiple','');const o=s.querySelectorAll('option');o[0].selected=true;o[1].selected=true;log('multiple',c.length,Array.from(c,x=>x.value).join(','));s.removeAttribute('multiple');log('single',c.length,c[0]?.value);o[0].remove();log('remove',c.length,c[0]?.value)});
test('select-private-state',()=>{const[f,s]=make('<option value=a>A</option><option value=b>B</option>'),o=s.querySelectorAll('option');let calls=0;for(const key of ['querySelectorAll','hasAttribute','getAttribute'])Object.defineProperty(s,key,{configurable:true,value(){calls++;return key==='querySelectorAll'?[]:null}});Object.defineProperty(s,'selectedIndex',{configurable:true,get(){calls++;return 99}});for(const x of o)for(const key of ['selected','value','textContent','hasAttribute','getAttribute'])Object.defineProperty(x,key,{configurable:true,get(){calls++;return key==='selected'?false:key==='hasAttribute'?()=>false:()=>null}});const p=HTMLSelectElement.prototype;log('get',Object.getOwnPropertyDescriptor(p,'selectedIndex').get.call(s),Object.getOwnPropertyDescriptor(p,'value').get.call(s),Object.getOwnPropertyDescriptor(p,'selectedOptions').get.call(s).length);Object.getOwnPropertyDescriptor(p,'value').set.call(s,'b');log('set',Object.getOwnPropertyDescriptor(p,'selectedIndex').get.call(s),Object.getOwnPropertyDescriptor(p,'value').get.call(s),JSON.stringify(Array.from(new FormData(f))),calls)});
test('select-brand-conversion',()=>{const[f,s]=make('<option value=a>A</option><option value=b>B</option>'),o=s.firstChild;for(const [p,key]of [[HTMLSelectElement.prototype,'selectedIndex'],[HTMLSelectElement.prototype,'value'],[HTMLSelectElement.prototype,'selectedOptions'],[HTMLOptionElement.prototype,'selected'],[HTMLOptionElement.prototype,'value'],[HTMLOptionElement.prototype,'text'],[HTMLOptionElement.prototype,'label'],[HTMLOptionElement.prototype,'defaultSelected'],[HTMLOptionElement.prototype,'index'],[HTMLOptionElement.prototype,'form']]){const d=Object.getOwnPropertyDescriptor(p,key);log(key,'get',attempt(()=>d.get.call({})));if(d.set)log(key,'set',attempt(()=>d.set.call({},'x')))}for(const v of [Symbol('s'),1n])log('index conversion',typeof v,attempt(()=>{s.selectedIndex=v}));for(const key of ['value','label','text']){o[key]=null;log(key,'null',o[key]);log(key,'symbol',attempt(()=>{o[key]=Symbol('s')}))}});
test('select-reentrant-conversion',()=>{const[f,s]=make('<option value=a>A</option><option value=b>B</option>');let calls=0;s.selectedIndex={valueOf(){calls++;s.innerHTML='<option value=c>C</option><option value=d>D</option>';return 1}};snap('index '+calls,f,s);s.value={toString(){calls++;s.innerHTML='<option value=e>E</option><option value=f>F</option>';return 'f'}};snap('value '+calls,f,s);const o=s.firstChild;o.text={toString(){calls++;return '  One\n Two  '}};log('text',calls,o.text,o.textContent,o.value);o.removeAttribute('value');log('value text',o.value);o.label='';log('empty label',o.label);o.defaultSelected=true;log('default',o.defaultSelected,o.hasAttribute('selected'),o.selected)});
test('option-owner-index',()=>{const f=document.createElement('form');f.id='outside';document.body.append(f);const[,s]=make('<option>A</option><option>B</option>','form=outside');document.body.append(s);const o=s.lastChild;log('external',o.index,o.form===f);o.remove();log('detached',o.index,o.form);const group=document.createElement('optgroup');group.append(o);s.prepend(group);log('group',o.index,o.form===f);s.firstChild.remove();s.remove();f.remove()});
test('select-bulk-mutation',()=>{const[f,s]=make('<option selected value=old>Old</option>');const fragment=document.createDocumentFragment();for(const value of ['a','b']){const o=document.createElement('option');o.value=value;o.selected=true;fragment.append(o)}s.prepend(fragment);snap('prepend two selected',f,s);s.selectedIndex=-1;const group=document.createElement('optgroup');group.innerHTML='<option value=c>C</option><option value=d selected>D</option>';s.append(group);snap('append group',f,s);const[f2,s2]=make('<option selected value=x>X</option>');s2.append(s.lastChild);snap('old owner',f,s);snap('new owner',f2,s2);s2.replaceChildren();snap('empty',f2,s2)});
test('select-size-disabled',()=>{const[f,s]=make('<option disabled>A</option><optgroup disabled><option>B</option></optgroup><option>C</option>');snap('default',f,s);s.selectedIndex=-1;s.setAttribute('size','2');snap('size2',f,s);s.setAttribute('size','1');snap('size1',f,s);s.selectedIndex=-1;s.firstChild.removeAttribute('disabled');snap('enable A',f,s);s.firstChild.setAttribute('disabled','');snap('disable selected A',f,s);s.selectedIndex=-1;s.setAttribute('size','+1suffix');snap('size prefix',f,s);s.selectedIndex=-1;s.removeAttribute('size');snap('size missing',f,s)});
test('select-dirty-defaults',()=>{for(const action of ['index','value','option']){const[f,s]=make('<option value=a>A</option><option value=b selected>B</option>'),o=s.lastChild;if(action==='index')s.selectedIndex=1;else if(action==='value')s.value='b';else o.selected=true;o.defaultSelected=false;log(action+' default false',o.defaultSelected,o.hasAttribute('selected'));snap(action+' remove default',f,s);o.defaultSelected=true;log(action+' default true',o.defaultSelected,o.hasAttribute('selected'));snap(action+' add default',f,s);f.reset();snap(action+' reset',f,s)}});
test('option-text-mutation',async()=>{const[f,s]=make('<option value=a>A</option>'),o=s.firstChild;let hooks=0;o.replaceChildren=o.appendChild=o.removeChild=()=>{hooks++;throw Error('author hook')};o.text='<b> Plain </b>';log('literal',o.text,o.textContent,o.innerHTML,hooks);o.removeAttribute('value');snap('submission',f,s);o.label='L';log('label',o.label,o.text);o.text='';log('empty',o.text,o.textContent,o.childNodes.length,hooks)});
test('option-disabled-selectors',()=>{const f=document.createElement('form');f.innerHTML='<fieldset disabled><select name=s><option value=a>A</option><optgroup disabled><option value=b>B</option></optgroup></select></fieldset>';const s=f.querySelector('select'),o=s.querySelectorAll('option');for(let i=0;i<o.length;i++)log(i,o[i].matches(':disabled'),o[i].matches(':enabled'),o[i].disabled);log('disabled select',s.matches(':disabled'),s.selectedIndex,JSON.stringify(Array.from(new FormData(f))))});
